import{_ as o,o as d,c as t,a2 as c}from"./chunks/framework.G0y0PQA7.js";const u=JSON.parse('{"title":"명령줄","description":"","frontmatter":{},"headers":[],"relativePath":"features/cli.md","filePath":"features/cli.md"}'),a={name:"features/cli.md"};function r(l,e,i,n,s,p){return d(),t("div",null,[...e[0]||(e[0]=[c(`<h1 id="명령줄" tabindex="-1">명령줄 <a class="header-anchor" href="#명령줄" aria-label="Permalink to &quot;명령줄&quot;">​</a></h1><p>같은 실행 파일(<code>relio</code>)로 화면 없이 내보내고, 가져오고, 비교하고, 합치고, 검사하고, DB와 주고받는 방법을 설명합니다. 빌드 스크립트나 CI에 넣기 좋습니다.</p><p>Git과 함께 쓰는 흐름은 빠른 시작의 <a href="/relio/quick/git">Git으로 함께 쓰기·합치기</a>에 있습니다.</p><h2 id="시작하기" tabindex="-1">시작하기 <a class="header-anchor" href="#시작하기" aria-label="Permalink to &quot;시작하기&quot;">​</a></h2><ul><li>명령줄에서 그냥 <code>relio</code>로 부르려면 설치 마지막 화면에서 **&quot;명령줄에서 relio 쓰기&quot;**를 켭니다(기본 꺼짐). 지금 사용자의 PATH에 설치 폴더를 더하고(관리자 권한 필요 없음), 제거하면 그 항목만 뺍니다. 새로 연 터미널부터 적용됩니다.</li><li>켜지 않았거나 설치 없이 쓰는 실행판이면 도움말 › Relio 정보나 도구 › 명령줄·AI 연결… 창의 <strong>명령줄 경로 복사</strong>로 지금 쓰는 실행 파일의 전체 경로를 따옴표째 복사해 <code>relio</code> 자리에 붙여 씁니다.</li><li>지금 PATH에 있는지는 도구 › <strong>명령줄·AI 연결…</strong> 창의 &quot;명령줄에서 relio 쓰기&quot;(켜짐 · 꺼짐)로 봅니다. 꺼짐이면 설치 파일을 다시 실행해 마침 페이지의 세 번째 칸 **&quot;명령줄에서 relio 쓰기&quot;**를 켭니다. 이미 켜져 있던 터미널은 다시 열어야 적용됩니다.</li><li><code>relio --help</code>, <code>relio export &lt;종류&gt; --help</code>, <code>relio import --help</code>, <code>relio diff --help</code>, <code>relio merge --help</code>, <code>relio lint --help</code>, <code>relio db &lt;명령&gt; --help</code>, <code>relio mcp --help</code>로 옵션을 봅니다.</li><li>출력 언어는 앱 언어를 따르고, 환경 변수 <code>RELIO_LANG</code>(<code>ko</code> · <code>en</code> · <code>ja</code> · <code>zh</code>)로 바꿀 수 있습니다.</li></ul><p>운영 체제에 따라 다른 것:</p><table tabindex="0"><thead><tr><th>항목</th><th>Windows</th></tr></thead><tbody><tr><td>설치한 실행 파일(기본 위치)</td><td><code>%LOCALAPPDATA%\\Relio\\relio.exe</code></td></tr><tr><td>실행판</td><td>압축을 푼 폴더의 <code>relio.exe</code></td></tr><tr><td>&quot;명령줄에서 relio 쓰기&quot;</td><td>사용자 PATH에 설치 폴더를 더함(제거하면 그 항목만 뺌)</td></tr><tr><td>실행판을 PATH에 넣기</td><td>실행판(zip)은 PATH를 바꾸지 않으므로 그 폴더를 PATH에 직접 더함</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>relio export ddl --input model.erm --output model.sql --db-version 17</span></span>
<span class="line"><span>relio export excel --input model.erm --output model.xlsx --template default_ko</span></span>
<span class="line"><span>relio export dbml --input model.erm --output model.dbml</span></span>
<span class="line"><span>relio export mermaid --input model.erm --output - --category 영업</span></span>
<span class="line"><span>relio export json --input model.erm --output model.json --include images,history</span></span>
<span class="line"><span>relio export java --input model.erm --output-dir src --style jpa</span></span>
<span class="line"><span>relio import auto --input schema.sql --output schema.erm</span></span>
<span class="line"><span>relio diff old.erm new.erm --format markdown --output diff.md --exit-code</span></span>
<span class="line"><span>relio merge base.erm mine.erm theirs.erm -o merged.erm --report -</span></span>
<span class="line"><span>relio lint model.erm --format markdown --fail-on error</span></span>
<span class="line"><span>relio db test --db PostgreSQL --server localhost --database app --user dev --password-env PGPASSWORD</span></span>
<span class="line"><span>relio db import --db MySQL --database shop --user dev --output shop.erm</span></span></code></pre></div><h2 id="relio-export" tabindex="-1">relio export <a class="header-anchor" href="#relio-export" aria-label="Permalink to &quot;relio export&quot;">​</a></h2><p><code>relio export &lt;종류&gt; --input &lt;모델.erm&gt; --output &lt;출력&gt;</code></p><ul><li><strong>종류</strong> — <code>ddl</code> · <code>image</code> · <code>html</code> · <code>excel</code> · <code>testdata</code> · <code>dictionary</code> · <code>translation</code> · <code>java</code> · <code>dbml</code> · <code>mermaid</code> · <code>markdown</code> · <code>json</code>.</li><li>옵션을 주지 않으면 <code>.erm</code>에 저장된 마지막 내보내기 설정을 씁니다.</li><li>종류마다 쓸 수 있는 옵션은 아래 &quot;종류별 옵션&quot; 표에 있습니다.</li><li><strong><code>--encoding</code></strong> — UTF-8(기본) · UTF-8 BOM · UTF-16LE · UTF-16BE · EUC-KR · CP949(MS949) · Shift_JIS · GBK. 모르는 이름은 오류입니다(조용히 UTF-8로 바꾸지 않음).</li><li><strong>표준 출력</strong> — <code>--output -</code>는 글 종류(<code>ddl</code> · <code>dictionary</code> · <code>translation</code> · <code>dbml</code> · <code>mermaid</code> · <code>markdown</code> · <code>json</code>)에서 표준 출력으로 냅니다.</li><li><code>relio export ddl</code>은 설계 검사의 오류(DDL 실행을 실패하게 하는 문제)가 있으면 표준 오류에 한 줄 알립니다.</li></ul><h3 id="종류별-옵션" tabindex="-1">종류별 옵션 <a class="header-anchor" href="#종류별-옵션" aria-label="Permalink to &quot;종류별 옵션&quot;">​</a></h3><p>모든 종류에 <code>--input &lt;모델.erm&gt;</code>이 있습니다. 켜고 끄는 옵션(<code>--no-…</code>)을 주지 않으면 <code>.erm</code>에 저장된 마지막 설정을 따릅니다.</p><table tabindex="0"><thead><tr><th>종류</th><th>출력</th><th>그 밖의 옵션</th></tr></thead><tbody><tr><td><code>ddl</code></td><td><code>--output</code></td><td><code>--db-product</code> · <code>--db-version</code> · <code>--environment</code>(테이블스페이스 환경) · <code>--category</code> · <code>--encoding</code> · <code>--line-feed</code> · <code>--comment on|off</code>(DB 주석) · <code>--inline-table-comment on|off</code> · <code>--inline-column-comment on|off</code> · <code>--comment-value description|logical|logical-description</code> · <code>--comment-replace-line-feed &lt;문자열&gt;</code> · <code>--no-comment-replace-line-feed</code> · <code>--set &lt;항목&gt;=true|false</code>(삭제·생성 문장 하나씩, 여러 번) · <code>--if-not-exists</code> · <code>--omit-schema</code> · <code>--native-types</code>(Oracle 23 이상 boolean) · <code>--no-sqlblanklines</code> · <code>--drop-tablespaces</code></td></tr><tr><td><code>image</code></td><td><code>--output</code>(확장자로 png·jpg·bmp·svg)</td><td><code>--with-category</code> · <code>--no-with-category</code>(카테고리별 그림) · <code>--category-dir</code></td></tr><tr><td><code>html</code></td><td><code>--output-dir</code></td><td><code>--no-image</code> · <code>--no-category-image</code></td></tr><tr><td><code>excel</code></td><td><code>--output</code>(.xlsx)</td><td><code>--template default_ko|default_en|default_ja|default_zh</code> 또는 <code>--template-file</code> · <code>--no-image</code> · <code>--logical-sheet-name</code> · <code>--physical-sheet-name</code> · <code>--category</code></td></tr><tr><td><code>dictionary</code></td><td><code>--output</code>(CSV)</td><td><code>--no-bom</code></td></tr><tr><td><code>translation</code></td><td><code>--output</code></td><td></td></tr><tr><td><code>testdata</code></td><td><code>--output-dir</code></td><td><code>--name &lt;테스트 데이터 이름&gt;</code>(꼭 필요, 여러 번) · <code>--format sql|dbunit-xml|dbunit-flat-xml|dbunit-excel</code> · <code>--encoding</code></td></tr><tr><td><code>java</code></td><td><code>--output-dir</code></td><td><code>--package</code> · <code>--suffix</code> · <code>--hibernate</code> · <code>--no-hibernate</code> · <code>--style plain|jpa</code> · <code>--jpa-namespace jakarta|javax</code> · <code>--jpa-legacy-date</code> · <code>--jpa-collections</code> · <code>--jpa-fk-as-value</code> · <code>--encoding</code></td></tr><tr><td><code>dbml</code></td><td><code>--output</code></td><td><code>--no-partials</code>(컬럼 그룹을 펼쳐 씀) · <code>--no-notes</code>(노트 빼기)</td></tr><tr><td><code>mermaid</code></td><td><code>--output</code></td><td><code>--no-alias</code>(논리명 별칭 빼기) · <code>--fence</code>(mermaid 코드 울타리) · <code>--split-categories</code>(카테고리마다 <code>&lt;이름&gt;-&lt;카테고리&gt;.mmd</code>)</td></tr><tr><td><code>markdown</code></td><td><code>--output</code></td><td><code>--no-diagram</code> · <code>--no-views</code> · <code>--tables-only</code> · <code>--by-category</code></td></tr><tr><td><code>json</code></td><td><code>--output</code></td><td><code>--include images,history</code> · <code>--exclude layout</code> · <code>--timestamp</code> · <code>--schema-version</code> · <code>--print-schema</code>(JSON Schema를 표준 출력으로)</td></tr></tbody></table><p><code>dbml</code> · <code>mermaid</code> · <code>markdown</code> · <code>json</code>은 <code>--category &lt;이름&gt;</code>(그 카테고리만) · <code>--encoding</code> · <code>--line-feed lf|crlf</code>(기본 <code>lf</code>)도 씁니다.</p><h3 id="출력-경로-규칙" tabindex="-1">출력 경로 규칙 <a class="header-anchor" href="#출력-경로-규칙" aria-label="Permalink to &quot;출력 경로 규칙&quot;">​</a></h3><ul><li>이미 있는 출력 파일은 묻지 않고 덮어쓰고, 출력 폴더가 없으면 만듭니다.</li><li>출력 경로가 입력 <code>.erm</code>과 같으면 쓰지 않고 오류로 끝납니다.</li><li><code>--output</code>을 주지 않으면 <code>.erm</code>에 저장된 경로를 쓰는데, <code>.erm</code>이 있는 폴더 안을 가리킬 때만입니다. 폴더 밖 절대 경로 · 다른 드라이브 · 네트워크 경로 · <code>..</code>이면 <code>--output</code>으로 지정하라는 오류가 납니다(남이 준 <code>.erm</code>이 다른 파일을 덮어쓰지 못하게).</li><li>확장자가 종류와 다르면 경고하고 씁니다.</li></ul><h2 id="relio-import" tabindex="-1">relio import <a class="header-anchor" href="#relio-import" aria-label="Permalink to &quot;relio import&quot;">​</a></h2><p><code>relio import &lt;형식&gt; --input &lt;파일|-&gt; --output &lt;새.erm&gt;</code></p><table tabindex="0"><thead><tr><th>옵션</th><th>설명</th></tr></thead><tbody><tr><td>형식</td><td><code>auto</code> · <code>ddl</code> · <code>dbml</code> · <code>mermaid</code> · <code>markdown</code></td></tr><tr><td><code>--input</code></td><td>파일, 또는 <code>-</code>(표준 입력)</td></tr><tr><td><code>--output</code></td><td>새 <code>.erm</code>. 이미 있으면 <code>--force</code>가 있어야 덮어씁니다.</td></tr><tr><td><code>--dialect</code></td><td>SQL 방언</td></tr><tr><td><code>--db</code></td><td>새 문서의 DB</td></tr><tr><td><code>--comment auto|description|logical</code></td><td>주석을 논리명·설명 중 어디에 넣을지</td></tr><tr><td><code>--name-case asis|db</code></td><td>따옴표 없는 이름을 그대로 둘지, DB 규칙대로 바꿀지</td></tr><tr><td><code>--encoding</code></td><td>입력 인코딩</td></tr><tr><td><code>--strict</code></td><td>경고가 있으면 만들지 않습니다.</td></tr></tbody></table><p>경고는 표준 오류에 <code>&lt;입력&gt;:&lt;줄&gt;:&lt;열&gt;: 경고: &lt;내용&gt;</code> 꼴로 나옵니다. <a href="/relio/features/import">가져오기와 다른 형식</a></p><h2 id="relio-diff" tabindex="-1">relio diff <a class="header-anchor" href="#relio-diff" aria-label="Permalink to &quot;relio diff&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>relio diff A.erm B.erm</span></span>
<span class="line"><span>relio diff --rev REV 파일.erm            # Git 저장소의 그 버전 ↔ 디스크</span></span>
<span class="line"><span>relio diff --rev REV1 --rev REV2 파일.erm</span></span></code></pre></div><table tabindex="0"><thead><tr><th>옵션</th><th>설명</th></tr></thead><tbody><tr><td><code>--format markdown|json|csv|sql</code></td><td><code>sql</code>은 A 구조의 DB를 B로 바꾸는 변경 SQL(비교 화면의 변경 SQL 만들기와 같음)</td></tr><tr><td><code>--group-by table|kind</code></td><td>Markdown을 테이블별·종류별로 묶습니다(기본 <code>table</code>).</td></tr><tr><td><code>--output</code></td><td>출력 파일. <code>-</code>이면 표준 출력</td></tr><tr><td><code>--include structure,docs,layout,settings</code></td><td>비교할 범위</td></tr><tr><td><code>--lang</code></td><td>출력 언어</td></tr><tr><td><code>--exit-code</code></td><td>차이가 있으면 종료 코드 4</td></tr></tbody></table><p>저장소에 아무것도 쓰지 않고 네트워크에 접속하지 않습니다. Git 비교 도구로도 쓸 수 있습니다: <code>git difftool -x &quot;relio diff&quot; -- 모델.erm</code>. <a href="/relio/features/git#비교-화면">Git과 합치기 › 비교 화면</a></p><h2 id="relio-merge" tabindex="-1">relio merge <a class="header-anchor" href="#relio-merge" aria-label="Permalink to &quot;relio merge&quot;">​</a></h2><p><code>relio merge 바탕.erm 내쪽.erm 바깥쪽.erm -o 결과.erm</code></p><ul><li>결과 파일에는 충돌 표시를 넣지 않습니다(늘 올바른 <code>.erm</code>). 충돌이 남으면 <code>--on-conflict ours|theirs</code>(기본 <code>ours</code>) 쪽 값을 넣고 종료 코드 5로 끝납니다.</li><li><code>--keep-numbers ours|theirs</code> — 번호를 지킬 쪽.</li><li><code>--report &lt;경로|-&gt;</code> · <code>--report-format markdown|json</code> — 충돌·자동 항목 보고서.</li><li><code>--label-base</code> · <code>--label-ours</code> · <code>--label-theirs</code> — 보고서의 이름표.</li><li><code>--no-sort</code> — 정렬 저장 끄기. <code>--lang</code> — 출력 언어.</li><li><code>-o</code>는 내 쪽 입력과 같은 경로여도 됩니다. 저장소에는 아무것도 쓰지 않습니다.</li></ul><h2 id="git-merge-driver" tabindex="-1">Git merge driver <a class="header-anchor" href="#git-merge-driver" aria-label="Permalink to &quot;Git merge driver&quot;">​</a></h2><p>저장소의 <code>.gitattributes</code>에 한 줄을 넣고 Git 설정에 드라이버를 등록하면 <code>git merge</code>·<code>git rebase</code>가 <code>.erm</code>을 모델 단위로 합칩니다. 충돌이 남으면(종료 코드 5) Git은 그 파일을 충돌로 남기고, Relio에서 열어 파일 › 비교·병합 ▸ › Git 병합 충돌 풀기…로 마저 풉니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># .gitattributes</span></span>
<span class="line"><span>*.erm text eol=lf merge=relio</span></span>
<span class="line"><span></span></span>
<span class="line"><span>git config merge.relio.name &quot;Relio model merge&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Windows (Git Bash) — 설치된 relio.exe 전체 경로</span></span>
<span class="line"><span>git config merge.relio.driver &#39;&quot;C:/Users/&lt;사용자&gt;/AppData/Local/Relio/relio.exe&quot; merge %O %A %B -o %A --label-base %S --label-ours %X --label-theirs %Y&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># relio가 PATH에 있을 때</span></span>
<span class="line"><span>git config merge.relio.driver &quot;relio merge %O %A %B -o %A --label-base %S --label-ours %X --label-theirs %Y&quot;</span></span></code></pre></div><ul><li>설치 때 &quot;명령줄에서 relio 쓰기&quot;를 켜지 않았으면 <code>relio</code>가 PATH에 없으므로, Windows에서는 <code>relio.exe</code> 전체 경로를 <code>/</code>로 적고 따옴표로 감쌉니다(위 첫 예). 도움말 › Relio 정보의 <strong>명령줄 경로 복사</strong>로 따옴표째 복사한 뒤 <code>\\</code>를 <code>/</code>로 바꿉니다.</li><li><code>.gitattributes</code>의 <code>text eol=lf</code>는 커밋 안의 줄 끝을 LF로 맞춥니다. ERMaster(CRLF)와 Relio(LF)를 섞어 쓰는 팀에서 줄 끝 차이 때문에 파일 전체가 바뀐 것으로 잡히지 않게 합니다.</li><li><code>--label-base %S</code>는 보고서의 바탕 이름표를 Git 임시 파일 이름 대신 공통 조상 이름으로 씁니다.</li><li>드라이버는 Git 설정이라 저장소에 따라가지 않습니다. <strong>ERMaster를 쓰는 팀원을 포함해 병합하는 사람 모두</strong> 자기 PC에 등록해야 합니다. 등록하지 않은 사람의 <code>git merge</code>는 줄 단위로 합쳐 충돌 표시가 남습니다.</li></ul><div class="warning custom-block"><p class="custom-block-title">주의</p><p>등록했지만 Git이 드라이버를 찾지 못하면(경로가 틀림 — 출력에 <code>relio: command not found</code> 같은 줄) Git은 충돌 표시 없이 <strong>내 쪽 파일만 남긴 채</strong> 충돌로 표시합니다. 그대로 <code>git add</code>하면 바깥 쪽 변경이 사라집니다. 등록한 뒤 <code>git config --get merge.relio.driver</code>의 경로를 그대로 붙여 <code>&quot;…/relio.exe&quot; --version</code>이 판 번호를 내는지, <code>git check-attr merge -- 모델.erm</code>이 <code>merge: relio</code>인지 꼭 확인하세요.</p></div><h2 id="relio-lint" tabindex="-1">relio lint <a class="header-anchor" href="#relio-lint" aria-label="Permalink to &quot;relio lint&quot;">​</a></h2><p><code>relio lint 모델.erm</code></p><table tabindex="0"><thead><tr><th>옵션</th><th>설명</th></tr></thead><tbody><tr><td><code>--format text|markdown|json</code></td><td>출력 형식</td></tr><tr><td><code>--output</code></td><td>출력 파일(기본 <code>-</code> 표준 출력)</td></tr><tr><td><code>--fail-on error|warning|info|none</code></td><td>이 심각도 이상 지적이 있으면 종료 코드 6(기본 <code>warning</code>)</td></tr><tr><td><code>--disable</code> · <code>--only</code></td><td>쉼표로 구분한 규칙 ID(예: <code>pk-missing</code>, <code>fk-no-index</code>, <code>reserved-word</code>). 모든 규칙 ID는 <a href="/relio/features/check#검사-규칙">설계 검사와 추천 › 검사 규칙</a> 표에 있습니다.</td></tr><tr><td><code>--db-version</code></td><td>검사 기준 DB 버전</td></tr><tr><td><code>--lang</code></td><td>출력 언어</td></tr></tbody></table><p>앱에서 예외로 한 것은 적용되지 않으므로(어느 PC에서나 같은 결과) 규칙은 <code>--disable</code>로 끕니다. <a href="/relio/features/check">설계 검사와 추천</a></p><h2 id="relio-db" tabindex="-1">relio db <a class="header-anchor" href="#relio-db" aria-label="Permalink to &quot;relio db&quot;">​</a></h2><table tabindex="0"><thead><tr><th>명령</th><th>하는 일</th></tr></thead><tbody><tr><td><code>relio db test</code></td><td>접속 시험</td></tr><tr><td><code>relio db export</code></td><td>DB로 내보내기</td></tr><tr><td><code>relio db import</code></td><td>DB에서 가져오기</td></tr><tr><td><code>relio db roundtrip</code></td><td>왕복 시험(차이가 있으면 종료 코드 4)</td></tr></tbody></table><p>암호는 <code>--password-env &lt;환경 변수&gt;</code>로 넘깁니다. 명령줄에 암호를 직접 쓰지 않습니다. <a href="/relio/features/database">DB 연동</a></p><h2 id="relio-mcp" tabindex="-1">relio mcp <a class="header-anchor" href="#relio-mcp" aria-label="Permalink to &quot;relio mcp&quot;">​</a></h2><p>AI 도구(Claude Code · Claude Desktop · Cursor 등)가 띄워 쓰는 로컬 MCP 서버입니다. 직접 실행하는 명령이 아니라 AI 도구에 한 번 등록합니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude mcp add --scope user relio -- relio mcp</span></span>
<span class="line"><span>claude mcp list</span></span>
<span class="line"><span>claude mcp remove relio --scope user</span></span></code></pre></div><ul><li><code>--scope</code>는 어느 폴더에서 AI 도구를 켤 때 연결할지입니다 — <code>user</code>(모든 폴더, 권장) · <code>local</code>(이 프로젝트 폴더에서만) · <code>project</code>(팀과 함께, <code>.mcp.json</code>을 커밋). AI가 볼 수 있는 파일과는 별개입니다.</li><li>옵션은 <code>--root &lt;폴더&gt;</code>(여러 번) · <code>--anonymize</code> · <code>--read-only</code>이고, <code>relio mcp --help</code>로 등록 예를 봅니다. PATH에 없을 때는 그 실행 파일의 등록 줄도 보여 줍니다.</li><li>도구 › <strong>명령줄·AI 연결…</strong> 창에서 범위를 골라 등록 · 지우기 줄을 복사할 수 있습니다.</li></ul><p>등록 범위 · Claude Desktop과 Cursor의 설정 · AI가 볼 수 있는 파일 · 안전 안내는 <a href="/relio/features/ai#등록하기">AI와 함께 쓰기</a>에 있습니다.</p><h2 id="종료-코드" tabindex="-1">종료 코드 <a class="header-anchor" href="#종료-코드" aria-label="Permalink to &quot;종료 코드&quot;">​</a></h2><table tabindex="0"><thead><tr><th>코드</th><th>뜻</th></tr></thead><tbody><tr><td>0</td><td>성공(경고 포함) — <code>diff --exit-code</code>면 같음</td></tr><tr><td>1</td><td>입력·옵션 오류(가져오기: 테이블을 하나도 찾지 못함, <code>--strict</code>에서 경고)</td></tr><tr><td>2</td><td>출력 쓰기 실패(가져오기: <code>--force</code> 없이 이미 있는 <code>.erm</code>)</td></tr><tr><td>3</td><td>이 DB로 바꿀 수 없음</td></tr><tr><td>4</td><td>차이 있음(<code>db roundtrip</code>, <code>diff --exit-code</code>)</td></tr><tr><td>5</td><td>병합 충돌이 남음(<code>merge</code>)</td></tr><tr><td>6</td><td><code>--fail-on</code> 단계 이상 지적이 있음(<code>lint</code>)</td></tr></tbody></table><h2 id="ci에서-쓰기" tabindex="-1">CI에서 쓰기 <a class="header-anchor" href="#ci에서-쓰기" aria-label="Permalink to &quot;CI에서 쓰기&quot;">​</a></h2><ul><li><strong>검사</strong> — <code>relio lint 모델.erm --fail-on error</code>로 오류가 있으면 빌드를 실패시킵니다.</li><li><strong>DDL 만들기</strong> — <code>relio export ddl --input 모델.erm --output 모델.sql --db-version 17</code>.</li><li><strong>변경 확인</strong> — <code>relio diff --rev main 모델.erm --format markdown --output diff.md</code>로 바뀐 내용을 문서로 남깁니다.</li><li><strong>변경 SQL</strong> — <code>relio diff 이전.erm 이후.erm --format sql --output alter.sql</code>.</li></ul>`,49)])])}const h=o(a,[["render",r]]);export{u as __pageData,h as default};
